insert into public.services (slug,title,summary,problem,scope,deliverables,industries,technologies,published,division_name) values ('environmental-assessment','Environmental Assessment & Impact Studies','Structured environmental assessments that give decision-makers a clear, evidence-based picture of environmental risk and opportunity.','Organisations often lack a reliable, documented understanding of their environmental impacts before planning, financing or approval decisions.',array['Baseline environmental data collection','Impact identification and significance rating','Mitigation and management recommendations','Reporting aligned to applicable frameworks']::text[],array['Environmental assessment report','Impact register','Mitigation & monitoring plan']::text[],array['Government & public institutions','NGOs & development organisations','Agriculture & agribusiness']::text[],array['Field survey methods','GIS mapping','Statistical analysis']::text[],true,'Environmental & Sustainability Solutions') on conflict(slug) do nothing;
