insert into public.publications (slug,title,type,category,excerpt,body,tags,featured,downloadable,published_at) values ('gis-remote-sensing-climate-action','Why GIS and Remote Sensing Are Now Essential for Credible Climate Action','Insight','Climate Technology','Carbon claims live or die on spatial evidence. This insight explains how GIS and remote sensing underpin credible carbon project assessment and MRV.',array['Climate finance increasingly depends on verifiable evidence. A carbon project that cannot demonstrate, with spatial data, what changed on the ground — and what would have happened without the project — will struggle to attract investment or pass verification.','GIS and remote sensing provide that evidence. Satellite imagery reveals land-cover change at scales no field team could cover alone. Geospatial databases organise project boundaries, baselines and monitoring indicators into an auditable record. Spatial analysis tests additionality: would this forest have been cleared without the project?','For MRV — monitoring, reporting and verification — these tools are not optional extras. They are the measurement backbone. Organisations that build spatial evidence into project design from the start avoid costly retrofits and credibility gaps later.','At CGS, our Climate & Carbon Solutions division combines GIS-supported assessment with MRV design so that climate claims rest on evidence, not assertion.']::text[],array['GIS','Remote Sensing','Carbon','MRV','Climate Technology']::text[],true,true,'2026-11-25') on conflict(slug) do nothing;
insert into public.publications (slug,title,type,category,excerpt,body,tags,featured,published_at) values ('digital-transformation-smes-kenya','Digital Transformation for SMEs: Start With the Process, Not the Software','Article','Digital Transformation','Many digital projects fail because they automate broken processes. A practical framework for SMEs to sequence transformation for real returns.',array['Small and medium enterprises across Kenya are under pressure to digitise — and many technology purchases disappoint. The common thread in failed projects is not the software; it is the absence of process clarity before the software arrives.','A more reliable sequence starts with mapping the current workflow, identifying where manual effort creates errors or delays, and only then selecting technology that fits the redesigned process. Dashboards built on clean, well-owned data outperform expensive platforms fed by fragmented spreadsheets.','CGS supports SMEs through exactly this sequence: digital maturity assessment, a transformation roadmap, and implementation support that keeps technology subordinate to business outcomes.']::text[],array['Digital Transformation','SMEs','Software','Kenya']::text[],true,'2026-11-25') on conflict(slug) do nothing;
insert into public.publications (slug,title,type,category,excerpt,body,tags,featured,published_at) values ('environmental-data-decisions','From Data Collection to Decisions: Making Environmental Monitoring Count','Article','Environmental Data','Monitoring programmes generate data; decisions require analysis. How to close the gap between collection and action.',array['Environmental monitoring programmes often produce impressive volumes of data — and very few decisions. The gap is rarely technical. It is structural: indicators are not tied to decisions, data quality is not assured, and analysis is treated as an afterthought.','Effective programmes define, up front, which decisions each indicator informs, what thresholds trigger action, and who owns the response. Data pipelines then serve those decisions, with visualisation designed for the people who must act.','Our Data Science & Analytics division helps organisations make this shift — from collecting data to acting on it.']::text[],array['Environmental Data','Monitoring','Analytics']::text[],false,'2026-11-25') on conflict(slug) do nothing;
insert into public.publications (slug,title,type,category,excerpt,body,tags,featured,published_at) values ('cypher-terra-platform-update','Cypher Terra: Environmental Intelligence, One Platform','News','Product News','Cypher Terra brings environmental information, GIS-related capabilities and community-oriented tools together in a single platform.',array['Cypher Terra, CGS''s environmental technology and intelligence platform, continues to evolve as a single home for environmental information, GIS-related capabilities, educational resources and community-oriented environmental solutions.','The platform is live and accessible at cypher-green-systems.vercel.app. Organisations interested in environmental information systems, community engagement tools or educational content are invited to explore it and speak with our team about deployment and collaboration.']::text[],array['Cypher Terra','Product','Environmental Technology']::text[],false,'2026-11-25') on conflict(slug) do nothing;
